Lemma parser_init_at M op ois q b :
  L5.u64_at RSEGS M op (pa_vp_parser PeCLayoutA.CADDR_A) -> L5.defined M op 384 -> PMSPA.accA M op 384 ->
  L5.u8_at RSEGS M (op + 8) 1 -> L5.u8_at RSEGS M (op + 9) 0 -> L5.u32_at RSEGS M (op + 12) 0 -> L5.u8_at RSEGS M (op + 16) 0 -> L5.u32_at RSEGS M (op + 20) 0 ->
  L5.u64_at RSEGS M (op + 32) (pa_vp_nullis PeCLayoutA.CADDR_A) -> L5.u64_at RSEGS M (op + 48) (pa_vp_nullbuf PeCLayoutA.CADDR_A) -> L5.u64_at RSEGS M (op + 56) (pa_classic_imp PeCLayoutA.CADDR_A) ->
  L5.u64_at RSEGS M (op + 112) (pa_vp_nullis_ios PeCLayoutA.CADDR_A) -> L5.u32_at RSEGS M (op + 144) 0 -> L5.u32_at RSEGS M (op + 148) 0 -> L5.u64_at RSEGS M (op + 152) (op + 48) ->
  L5.u64_at RSEGS M (op + 160) (pa_classic_imp PeCLayoutA.CADDR_A) -> PM.zeros_at M (op + 168) 80 ->
  L5.u64_at RSEGS M (op + 264) ois -> L5.u64_at RSEGS M (op + 272) (ois + 16) -> L5.u64_at RSEGS M (op + 288) q -> L5.u64_at RSEGS M (op + 296) PM.CHUNK ->
  L5.u64_at RSEGS M (op + 304) q -> L5.u64_at RSEGS M (op + 312) 0 ->
  q mod 16 = 0 -> L5.defined M q PM.CHUNK -> PMSPA.accA M q PM.CHUNK ->
  L5.u32_at RSEGS M (op + 320) PM.MAX_DEPTH -> L5.u64_at RSEGS M (op + 328) PM.MAX_ITEMS -> L5.u8_at RSEGS M (op + 336) 0 ->
  PM.vec_at RSEGS PMSPA.accA PMSPA.annA M (op + 360) b 0 [PM.ps_root] -> 0 <= op -> op + 384 <= 2 ^ 64 ->
  PM.parser_at RSEGS PeCLayoutA.CADDR_A PMSPA.accA PMSPA.annA M op ois (PMSPA.parser_init q b).
Proof.
